-- Quest items: 33 world objects that hold an item quests ask for, spawned where the official game has them.
-- 2026_11_19_937_world_everlake_quest_item_objects.sql: the ForeverTracker Forge's spawn script for its 33 Ready objects (2026-11-19 11:06), renumbered.
--
-- Each object below is a world object the realm knows (gameobject_template) and that holds a quest item, but that
-- had no spawn, so the item could not be obtained and its quests could not be finished. Positions are converted
-- from Wowhead Forever's map coordinates by the tracker's locator; heights come from the realm's maps and vmaps
-- (the floor nearest an existing spawn under a roof or on a bridge). Six more points had no height the locator could
-- read and are left out. Respawn 300 s.
--
--   19021   Rusty Chest (30): Iron Pommel, Ashenvale
--   144064  Gordunni Dirt Mound (26): Gordunni Cobalt, Feralas
--   175264  Broodling Essence (28): Broodling Essence, Burning Steppes
--   175322  Forged Seal of Ascension (7): Forged Seal of Ascension, Dustwallow Marsh
--   177241  Araj's Phylactery (5): Araj's Scarab, Western Plaguelands
--   177624  Xabraxxis' Demon Bag (4): Talisman of Corruption, Darkshore
--   424002  Kurzen Supply Crate (1): Kurzen Fighter's Uniform, Stranglethorn Vale
--   424264  Grave (1): Theramore Echo, Dustwallow Marsh
--   424265  Grave (1): Swamp Echo, Swamp of Sorrows
--   424267  Grave (1): Arathi Echo, Arathi Highlands
--   582187  Petrified Tree (19): Petrified Bark, Shen'dralas
--   587299  Tear of Theradras (2): Tear of Theradras, Desolace
--   607122  Pylon Shard (1): Pylon Fragment, Desolace
--   607123  Pylon Shard (1): Pylon Shard, Desolace
--   612073  Cookie's Feast (16): Expiring Crab Cake, Wetlands
--   612090  Fishing Rack (29): Camper's Lure, Stranglethorn Vale
--   613836  Burning Keystone (1): Burning Keystone, Desolace
--   620422  Riverweed (30): Riverweed, Riverglades
--   625779  Track (3): Pawprint Tracing, Riverglades
--   654618  Rog'mar Supply Crate (15): Rog'mar Supply Crate, Riverglades
--   656100  Blade of House Perenolde (1): Blade of House Perenolde, Alterac Mountains
--   656101  Royal Aegis of Perenolde (1): Royal Aegis of Perenolde, Alterac Mountains
--   665270  Purple Berry Bush (2): Dark Purple Berries, Stonetalon Mountains
--   666694  Gnomish Garbage (30): Desert Debris, Tanaris
--   667676  Pristine Mattock (1): Pristine Mattock, Badlands
--   670348  Homebrew Hops (3): Sack of Homebrew Hops, Hillsbrad Foothills
--   671892  Razormaw Eggs (13): Perfect Razormaw Egg, Wetlands
--   671931  Razormaw Egg (29): Perfect Razormaw Egg, Wetlands
--   672334  Dragonmaw Armaments (12): Dragonmaw Armaments, Wetlands
--   672336  Dragonmaw Armaments (9): Dragonmaw Armaments, Wetlands
--   672337  Dragonmaw Armaments (13): Dragonmaw Armaments, Wetlands
--   673206  Stolen Explosives (6): Stolen Explosives, Wetlands
--   673431  Kurothel's Knapsack (3): Vine-Wrapped Scroll, Ashenvale
--
-- Guids: objects 920007000 to 920007343, a block of their own after file 931's creatures (920006049).
-- A spawn is only added while its guid is free, its template exists and that object has no spawn at all yet (a
-- later import that spawns one of them first wins). Not checked in game: the heights of a few points (a fishing rack
-- in the water off Stranglethorn, objects on slopes) may need a nudge.
--
-- Never edit this file once it is deployed: a later fix is a new file. Running it again changes nothing.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`guid` bigint unsigned NOT NULL, `id` int unsigned NOT NULL, `map` smallint unsigned NOT NULL,
  `x` float NOT NULL, `y` float NOT NULL, `z` float NOT NULL, `o` float NOT NULL, `r2` float NOT NULL, `r3` float NOT NULL, `respawn` int NOT NULL,
  `add` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`guid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- the objects that still have no spawn at all, whose template exists, at guids still free
UPDATE `everlake_import_stage` s SET s.`add` = 1
WHERE EXISTS (SELECT 1 FROM `gameobject_template` t WHERE t.`entry` = s.`id`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject` g WHERE g.`guid` = s.`guid`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject` g WHERE g.`id` = s.`id`);

  `rotation0`, `rotation1`, `rotation2`, `rotation3`, `spawntimesecs`, `animprogress`, `state`, `VerifiedBuild`)
SELECT `guid`, `id`, `map`, '0', `x`, `y`, `z`, `o`, 0, 0, `r2`, `r3`, `respawn`, 255, 1, 0 FROM `everlake_import_stage` WHERE `add` = 1;

SELECT 'gameobject', s.`guid`, '2026_11_19_937_world_everlake_quest_item_objects.sql', 'forge-locator@2026-11-19 (wowhead-forever map + realm maps/vmaps)'
FROM `everlake_import_stage` s WHERE s.`add` = 1
ON DUPLICATE KEY UPDATE `file` = '2026_11_19_937_world_everlake_quest_item_objects.sql', `note` = 'forge-locator@2026-11-19 (wowhead-forever map + realm maps/vmaps)';

DROP TEMPORARY TABLE `everlake_import_stage`;

COMMIT;
